  1	package mcpsignals
  2	
  3	import (
  4		"context"
  5		"encoding/json"
  6		"errors"
  7		"net/http"
  8		"strings"
  9		"time"
 10	
 11		"github.com/modelcontextprotocol/go-sdk/auth"
 12		"github.com/modelcontextprotocol/go-sdk/jsonrpc"
 13		"github.com/modelcontextprotocol/go-sdk/mcp"
 14	)
 15	
 16	// Identity is supplied only by the application. Empty fields become null.
 17	type Identity struct {
 18		UserID string
 19		OrgID  string
 20	}
 21	
 22	// CallContext contains detached metadata for an application identity resolver.
 23	// No user identity is inferred from client metadata, arguments or headers.
 24	type CallContext struct {
 25		SessionID     string
 26		ClientName    string
 27		ClientVersion string
 28		Transport     string
 29		// TokenInfo is this request's verified bearer token, set by the SDK's
 30		// auth.RequireBearerToken on streamable HTTP. Nil otherwise. Read-only.
 31		TokenInfo *auth.TokenInfo
 32		// Header is a copy of this request's HTTP headers, nil for other transports.
 33		Header http.Header
 34	}
 35	
 36	// Options configures instrumentation. Supply the same name/version passed to
 37	// mcp.NewServer: the SDK does not expose the server's Implementation publicly.
 38	// Configure once, before connecting clients. Callbacks must be concurrency-safe.
 39	type Options struct {
 40		ServerName       string
 41		ServerVersion    string
 42		Buffer           BufferOptions
 43		CaptureArguments bool
 44		Redaction        Redaction
 45		ResolveIdentity  func(context.Context, CallContext) (Identity, error)
 46		// Transport is "stdio", "http", or empty. A request with HTTP headers
 47		// (streamable HTTP) always records "http". Otherwise this value is used, and
 48		// empty means "stdio", as in Node/Python. Set "http" for the legacy SSE
 49		// transport, which exposes no headers to middleware.
 50		Transport string
 51	}
 52	
 53	// Handle owns the telemetry lifecycle, not the MCP server or its sinks.
 54	type Handle struct {
 55		Server  *mcp.Server
 56		buffer  *EventBuffer
 57		options Options
 58	}
 59	
 60	// Instrument adds supported receiving middleware without changing tool handlers
 61	// or registration APIs. Existing and subsequently registered tools are observed.
 62	// Call once per server, before serving clients. Middleware added earlier runs
 63	// inside this one, so ResolveIdentity cannot see context values it adds.
 64	func Instrument(server *mcp.Server, o Options) (*Handle, error) {
 65		if server == nil || o.ServerName == "" {
 66			return nil, errors.New("mcpsignals: server and server name are required")
 67		}
 68		if o.Transport != "" && o.Transport != "stdio" && o.Transport != "http" {
 69			return nil, errors.New("mcpsignals: transport must be stdio, http, or empty")
 70		}
 71		o.Redaction.Allow = append([]string(nil), o.Redaction.Allow...)
 72		o.Redaction.Deny = append([]string(nil), o.Redaction.Deny...)
 73		b, err := NewEventBuffer(o.Buffer)
 74		if err != nil {
 75			return nil, err
 76		}
 77		h := &Handle{Server: server, buffer: b, options: o}
 78		server.AddReceivingMiddleware(h.middleware)
 79		return h, nil
 80	}
 81	
 82	// Flush waits for previously started writes and flushes queued events.
 83	func (h *Handle) Flush(ctx context.Context) error { return h.buffer.Flush(ctx) }
 84	
 85	// Close drains telemetry after the application has stopped and drained requests.
 86	func (h *Handle) Close(ctx context.Context) error { return h.buffer.Close(ctx) }
 87	
 88	// Stats returns buffer overflow and sink failure counters.
 89	func (h *Handle) Stats() BufferStats { return h.buffer.Stats() }
 90	
 91	func (h *Handle) middleware(next mcp.MethodHandler) mcp.MethodHandler {
 92		return func(ctx context.Context, method string, req mcp.Request) (mcp.Result, error) {
 93			call, ok := req.(*mcp.CallToolRequest)
 94			if method != "tools/call" || !ok || call == nil || call.Params == nil {
 95				return next(ctx, method, req)
 96			}
 97			start := time.Now()
 98			// A handler may replace Params fields; record what the call arrived with.
 99			name, args := call.Params.Name, call.Params.Arguments
100			// Deliberately no recovery around next: handler errors/panics belong to the SDK.
101			result, err := next(ctx, method, req)
102			duration := time.Since(start)
103			if r, ok := result.(*mcp.CallToolResult); ok && r != nil && r.NeedsInput() {
104				// Not a completed invocation: the client answers the input requests
105				// and retries, and that continuation is recorded.
106				return result, err
107			}
108			if isUnknownTool(err) {
109				// Node/Python record registered tools only; a probe with arbitrary
110				// names must not create rows with client-chosen tool names.
111				return result, err
112			}
113			// Identity and redaction run after the handler, as in Node/Python, so a
114			// slow resolver neither delays the handler nor shifts ts.
115			event := h.prepare(ctx, call, name, args)
116			event.TS = start.UTC()
117			event.DurationMS = durationMS(duration)
118			h.record(event, result, err)
119			return result, err
120		}
121	}
122	
123	func (h *Handle) prepare(ctx context.Context, req *mcp.CallToolRequest, name string, args json.RawMessage) (e ToolCallEvent) {
124		e = ToolCallEvent{EventType: "tool_call", ServerName: h.options.ServerName, ServerVersion: optional(h.options.ServerVersion), ToolName: truncate(name, 128), RequestBytes: len(args)}
125		// Telemetry never changes the invocation, even if SDK metadata access fails.
126		defer func() { _ = recover() }()
127		e.Arguments = captureArguments(args, h.options.CaptureArguments, h.options.Redaction)
128		c := CallContext{Transport: h.options.Transport}
129		if req.Extra != nil {
130			c.TokenInfo = req.Extra.TokenInfo
131			if req.Extra.Header != nil {
132				c.Transport = "http"
133				if h.options.ResolveIdentity != nil {
134					c.Header = req.Extra.Header.Clone()
135				}
136			}
137		}
138		if c.Transport == "" {
139			c.Transport = "stdio"
140		}
141		if req.Session != nil {
142			c.SessionID = req.Session.ID()
143		}
144		if info := req.ClientInfo(); info != nil {
145			c.ClientName = info.Name
146			c.ClientVersion = info.Version
147		}
148		e.Transport = optional(c.Transport)
149		e.SessionID = optional(c.SessionID)
150		e.ClientName = bounded(c.ClientName, 128)
151		e.ClientVersion = bounded(c.ClientVersion, 128)
152		// A resolver error or panic leaves user_id and org_id null.
153		if h.options.ResolveIdentity != nil {
154			if identity, err := h.options.ResolveIdentity(ctx, c); err == nil {
155				e.UserID = optional(identity.UserID)
156				e.OrgID = optional(identity.OrgID)
157			}
158		}
159		return e
160	}
161	
162	func (h *Handle) record(e ToolCallEvent, result mcp.Result, callErr error) {
163		setOutcome(&e, result, callErr)
164		h.buffer.Push(e)
165	}
166	
167	// setOutcome fills the outcome fields. A panic keeps the fields set so far,
168	// so the call is still recorded.
169	func setOutcome(e *ToolCallEvent, result mcp.Result, callErr error) {
170		defer func() { _ = recover() }()
171		e.Success = callErr == nil
172		var message string
173		var declared string
174		if callErr != nil {
175			message = callErr.Error()
176		} else if r, ok := result.(*mcp.CallToolResult); ok && r != nil {
177			e.ResponseBytes = serializedSize(r)
178			e.Success = !r.IsError
179			if r.IsError {
180				var parts []string
181				for _, content := range r.Content {
182					if text, ok := content.(*mcp.TextContent); ok && text != nil {
183						parts = append(parts, text.Text)
184					}
185				}
186				message = strings.Join(parts, " ")
187				switch value := r.Meta[ErrorKindMetaKey].(type) {
188				case string:
189					declared = value
190				case ErrorKind:
191					declared = string(value)
192				}
193			}
194		}
195		if !e.Success {
196			message = truncate(message, 2000)
197			e.ErrorMessage = optional(message)
198			kind := ClassifyError(message)
199			if IsErrorKind(declared) {
200				kind = ErrorKind(declared)
201			}
202			if kind != "" {
203				e.ErrorKind = &kind
204			}
205		}
206	}
207	
208	// isUnknownTool matches the SDK's rejection of a tools/call for a name that
209	// is not registered (go-sdk v1.8.0 server.go callTool).
210	func isUnknownTool(err error) bool {
211		var wire *jsonrpc.Error
212		return errors.As(err, &wire) && wire.Code == jsonrpc.CodeInvalidParams && strings.HasPrefix(wire.Message, "unknown tool ")
213	}
214	
215	// durationMS rounds to the nearest millisecond, like Node's Math.round, so
216	// rows from every package agree for sub-millisecond calls.
217	func durationMS(d time.Duration) int64 { return d.Round(time.Millisecond).Milliseconds() }
218	
219	type byteCounter int
220	
221	func (c *byteCounter) Write(p []byte) (int, error) { *c += byteCounter(len(p)); return len(p), nil }
222	
223	// serializedSize is len(json.Marshal(v)) without keeping a copy of the output.
224	func serializedSize(v any) (size int) {
225		defer func() { _ = recover() }()
226		var n byteCounter
227		if json.NewEncoder(&n).Encode(v) != nil {
228			return 0
229		}
230		return int(n) - 1 // Encode appends a newline.
231	}
