  3	import (
  4		"context"
  5		"errors"
  6		"fmt"
  7		"sync"
  8		"time"
  9	)
 10	
 11	// BufferOptions configures best-effort delivery. Zero values select defaults.
 12	type BufferOptions struct {
 13		Sinks         []Sink
 14		BufferSize    int           // Automatic size threshold; default 20.
 15		FlushInterval time.Duration // Default 5 seconds.
 16		Manual        bool          // Disable all automatic writes, including size-triggered writes.
 17		MaxQueueSize  int           // Drop newest on overflow; default 1000 pending events.
 18		WriteTimeout  time.Duration // Automatic flush timeout; default 10 seconds.
 19	}
 20	
 21	// BufferStats reports cumulative delivery failures, without logging payloads.
 22	type BufferStats struct {
 23		Dropped    uint64 // Rejected because the queue was full or the buffer closed.
 24		SinkErrors uint64
 25	}
 26	
 27	// EventBuffer is a bounded, concurrency-safe queue. Push never calls a sink.
 28	// Flush and Close return sink errors; automatic failures are counted in Stats.
 29	// A failed batch is not retried (a sink may have partially committed it).
 30	// Create one with NewEventBuffer. The zero value drops every event and returns
 31	// an error from Flush and Close.
 32	type EventBuffer struct {
 33		mu      sync.Mutex
 34		queue   []ToolCallEvent
 35		closed  bool
 36		stats   BufferStats
 37		options BufferOptions
 38		gate    chan struct{}
 39		wake    chan struct{}
 40		stop    chan struct{}
 41		done    chan struct{}
 42	}
 43	
 44	var errUninitialized = errors.New("mcpsignals: EventBuffer must be created with NewEventBuffer")
 45	
 46	// initialized reports whether NewEventBuffer built b; it sets every channel.
 47	func (b *EventBuffer) initialized() bool { return b.done != nil }
 48	
 49	// NewEventBuffer starts one worker unless Manual is set. No network calls are
 50	// made until events are flushed. Call Close after stopping/draining the server.
 51	func NewEventBuffer(o BufferOptions) (*EventBuffer, error) {
 52		if o.BufferSize < 0 || o.FlushInterval < 0 || o.MaxQueueSize < 0 || o.WriteTimeout < 0 {
 53			return nil, errors.New("mcpsignals: buffer settings must not be negative")
 54		}
 55		if o.BufferSize == 0 {
 56			o.BufferSize = 20
 57		}
 58		if o.FlushInterval == 0 {
 59			o.FlushInterval = 5 * time.Second
 60		}
 61		if o.MaxQueueSize == 0 {
 62			o.MaxQueueSize = 1000
 63		}
 64		if o.WriteTimeout == 0 {
 65			o.WriteTimeout = 10 * time.Second
 66		}
 67		o.Sinks = append([]Sink(nil), o.Sinks...)
 68		for _, sink := range o.Sinks {
 69			if sink == nil {
 70				return nil, errors.New("mcpsignals: nil sink")
 71			}
 72		}
 73		b := &EventBuffer{options: o, gate: make(chan struct{}, 1), wake: make(chan struct{}, 1), stop: make(chan struct{}), done: make(chan struct{})}
 74		if o.Manual {
 75			close(b.done)
 76		} else {
 77			go b.run()
 78		}
 79		return b, nil
 80	}
 81	
 82	// Push accepts an immutable event snapshot. False means closed or full; both
 83	// are counted in Stats.Dropped. Callers must not mutate accepted event data.
 84	func (b *EventBuffer) Push(e ToolCallEvent) bool {
 85		b.mu.Lock()
 86		defer b.mu.Unlock()
 87		if b.closed || len(b.queue) >= b.options.MaxQueueSize {
 88			b.stats.Dropped++
 89			return false
 90		}
 91		b.queue = append(b.queue, e)
 92		if !b.options.Manual && len(b.queue) >= b.options.BufferSize {
 93			select {
 94			case b.wake <- struct{}{}:
 95			default:
 96			}
 97		}
 98		return true
 99	}
100	
101	// Stats returns a concurrency-safe copy of the counters.
102	func (b *EventBuffer) Stats() BufferStats { b.mu.Lock(); defer b.mu.Unlock(); return b.stats }
103	
104	// Flush waits for earlier writes and attempts all events queued when it obtains
105	// the flush lock. A canceled context before dequeue preserves pending events.
106	// After dequeue the batch is attempted once, even on cancellation or failure.
107	// Sinks must honor ctx; Go cannot interrupt arbitrary user code.
108	func (b *EventBuffer) Flush(ctx context.Context) error {
109		if !b.initialized() {
110			return errUninitialized
111		}
112		if err := ctx.Err(); err != nil {
113			return err
114		}
115		select {
116		case b.gate <- struct{}{}:
117		case <-ctx.Done():
118			return ctx.Err()
119		}
120		defer func() { <-b.gate }()
121		if err := ctx.Err(); err != nil {
122			return err
123		}
124		b.mu.Lock()
125		batch := b.queue
126		b.queue = nil
127		b.mu.Unlock()
128		if len(batch) == 0 {
129			return nil
130		}
131		var errs []error
132		for i, sink := range b.options.Sinks {
133			if err := writeSink(ctx, sink, batch); err != nil {
134				b.mu.Lock()
135				b.stats.SinkErrors++
136				b.mu.Unlock()
137				errs = append(errs, fmt.Errorf("mcpsignals: sink %d: %w", i, err))
138			}
139		}
140		return errors.Join(errs...)
141	}
142	
143	func writeSink(ctx context.Context, sink Sink, batch []ToolCallEvent) (err error) {
144		defer func() {
145			if recover() != nil {
146				err = errors.New("sink panicked")
147			}
148		}()
149		return sink.Write(ctx, batch)
150	}
151	
152	// Close stops accepting events and stops the worker, then drains pending and
153	// in-flight writes. It is idempotent and may be retried with a fresh context
154	// after a timeout. Stop and drain MCP requests before calling Close.
155	// Sink ownership remains with the application; Close does not close sinks.
156	func (b *EventBuffer) Close(ctx context.Context) error {
157		if !b.initialized() {
158			return errUninitialized
159		}
160		b.mu.Lock()
161		if !b.closed {
162			b.closed = true
163			close(b.stop)
164		}
165		b.mu.Unlock()
166		select {
167		case <-b.done:
168		case <-ctx.Done():
169			return ctx.Err()
170		}
171		return b.Flush(ctx)
172	}
173	
174	func (b *EventBuffer) run() {
175		defer close(b.done)
176		ticker := time.NewTicker(b.options.FlushInterval)
177		defer ticker.Stop()
178		for {
179			select {
180			case <-b.stop:
181				return
182			case <-ticker.C:
183			case <-b.wake:
184			}
185			// Prefer shutdown over a buffered wakeup.
186			select {
187			case <-b.stop:
188				return
189			default:
190			}
191			// An idle tick needs no timeout context or flush lock.
192			b.mu.Lock()
193			idle := len(b.queue) == 0
194			b.mu.Unlock()
195			if idle {
196				continue
197			}
198			ctx, cancel := context.WithTimeout(context.Background(), b.options.WriteTimeout)
199			_ = b.Flush(ctx)
200			cancel()
201		}
202	}

